import{_ as n,a0 as i,w as c,s,ao as d,I as r,x as o,a1 as p,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"在Linux命令行下令人惊叹的惊叹号（!） | LCTT x X-CMD","titleTemplate":false,"description":"在Linux命令行下令人惊叹的惊叹号（!） | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux命令行下令人惊叹的惊叹号（!） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux命令行下令人惊叹的惊叹号（!） | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150518 10 Amazing and Mysterious Uses of Symbol or Operator in Linux Commands","title":"在Linux命令行下令人惊叹的惊叹号（!）","tag":"201506","desc":""},"relativePath":"201506/20150518 10 Amazing and Mysterious Uses of Symbol or Operator in Linux Commands.md","filePath":"[post].md"}'),m={name:"201506/20150518 10 Amazing and Mysterious Uses of Symbol or Operator in Linux Commands.md"};function l(u,e,h,f,x,w){const t=i("Link");return c(),s("div",null,[e[18]||(e[18]=d(`<h1 id="在linux命令行下令人惊叹的惊叹号" tabindex="-1">在Linux命令行下令人惊叹的惊叹号（!） <a class="header-anchor" href="#在linux命令行下令人惊叹的惊叹号" aria-label="Permalink to “在Linux命令行下令人惊叹的惊叹号（!）”">​</a></h1><p><code>&#39;!&#39;</code>符号在Linux中不但可以用作否定符号，还可以用来从历史命令记录中取出命令或不加修改的执行之前运行的命令。下面的所有命令都已经在Bash Shell中经过确切地检验。尽管我没有试过，但大多都不能在别的Shell中运行。这里我们介绍下Linux命令行中符号<code>&#39;!&#39;</code>那惊人和奇妙的用法。</p><h3 id="_1-使用数字从历史命令列表中找一条命令来执行" tabindex="-1">1. 使用数字从历史命令列表中找一条命令来执行 <a class="header-anchor" href="#_1-使用数字从历史命令列表中找一条命令来执行" aria-label="Permalink to “1. 使用数字从历史命令列表中找一条命令来执行”">​</a></h3><p>您也许没有意识到您可以从历史命令列表（之前已经执行的命令集）中找出一条来运行。首先，通过&quot;history&quot;命令查找之前命令的序号。</p><pre><code>$ history
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/history-Command.gif" alt="使用history命令找到最后执行的命令"></p><p><em>使用history命令找到最后执行的命令</em></p><p>现在，只需要使用历史命令输出中显示在该命令前面的数字便可以运行这个命令。例如，运行一个在<code>history</code>输出中编号是1551的命令。</p><pre><code>$ !1551
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/Run-Commands-By-number.gif" alt="使用命令ID来执行最后运行的命令"></p><p><em>使用命令ID来执行最后运行的命令</em></p>`,11)),r("p",null,[e[1]||(e[1]=o("这样，编号为1551的命令（上面的例子是",-1)),p(t,{href:"http://www.tecmint.com/12-top-command-examples-in-linux/"},{default:a(()=>[...e[0]||(e[0]=[o("top命令",-1)])]),_:1}),e[2]||(e[2]=o("）便运行了。这种通过ID号来执行之前的命令的方式很有用，尤其是在这些命令都很长的情况下。您只需要使用",-1)),e[3]||(e[3]=r("strong",null,"![history命令输出的序号]",-1)),e[4]||(e[4]=o("便可以调用它。",-1))]),e[19]||(e[19]=d(`<h3 id="_2-运行之前的倒数第二个、第七个命令等" tabindex="-1">2. 运行之前的倒数第二个、第七个命令等 <a class="header-anchor" href="#_2-运行之前的倒数第二个、第七个命令等" aria-label="Permalink to “2. 运行之前的倒数第二个、第七个命令等”">​</a></h3><p>您可以以另一种方式来运行之前执行的命令，通过使用-1代表最后的命令，-2代表倒数第二个命令，-7代表倒数第七个命令等。</p><p>首先使用history命令来获得执行过的命令的列表。<strong>history命令的执行很有必要</strong>，因为您可以通过它来确保没有<code>rm command &gt; file</code>或其他会导致危险的命令。接下来执行倒数第六个、第八个、第十个命令。</p><pre><code>$ history
$ !-6
$ !-8
$ !-10
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/3.gif" alt="通过负数序号运行之前执行的命令"></p><p><em>通过负数序号运行之前执行的命令</em></p><h3 id="_3-传递最后执行的命令的参数-以方便的运行新的命令" tabindex="-1">3. 传递最后执行的命令的参数，以方便的运行新的命令 <a class="header-anchor" href="#_3-传递最后执行的命令的参数-以方便的运行新的命令" aria-label="Permalink to “3. 传递最后执行的命令的参数，以方便的运行新的命令”">​</a></h3><p>我需要显示<code>/home/$USER/Binary/firefox</code>文件夹的内容，因此我执行：</p><pre><code>$ ls /home/$USER/Binary/firefox
</code></pre><p>接下来，我意识到我应该执行&#39;ls -l&#39;来查看哪个文件是可执行文件。因此我应该重新输入整个命令么？不，我不需要。我仅需要在新的命令中带上最后的参数，类似：</p><pre><code>$ ls -l !$
</code></pre><p>这里<code>!$</code>将把最后执行的命令的参数传递到这个新的命令中。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/4.gif" alt="将上一个命令的参数传递给新命令"></p><p><em>将上一个命令的参数传递给新命令</em></p><h3 id="_4-如何使用-来处理两个或更多的参数" tabindex="-1">4. 如何使用!来处理两个或更多的参数 <a class="header-anchor" href="#_4-如何使用-来处理两个或更多的参数" aria-label="Permalink to “4. 如何使用!来处理两个或更多的参数”">​</a></h3><p>比如说我在桌面创建了一个文本文件file1.txt。</p><pre><code>$ touch /home/avi/Desktop/1.txt
</code></pre><p>然后在cp命令中使用绝对路径将它拷贝到<code>/home/avi/Downloads</code>。</p><pre><code>$ cp /home/avi/Desktop/1.txt /home/avi/downloads
</code></pre><p>这里，我们给cp命令传递了两个参数。第一个是<code>/home/avi/Desktop/1.txt</code>，第二个是<code>/home/avi/Downloads</code>。让我们分别处理他们，使用<code>echo [参数]</code>来打印两个不同的参数。</p><pre><code>$ echo &quot;1st Argument is : !^&quot;
$ echo &quot;2nd Argument is : !cp:2&quot;
</code></pre><p>注意第一个参数可以使用<code>&quot;!^&quot;</code>进行打印，其余的命令可以通过<code>&quot;![命令名]:[参数编号]&quot;</code>打印。</p><p>在上面的例子中，第一个命令是<code>cp</code>，第二个参数也需要被打印。因此是<code>&quot;!cp:2&quot;</code>，如果任何命令比如xyz运行时有5个参数，而您需要获得第四个参数，您可以使用<code>&quot;!xyz:4&quot;</code>。所有的参数都可以通过<code>&quot;!*&quot;</code>来获得。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/5.gif" alt="处理两个或更多的参数"></p><p><em>处理两个或更多的参数</em></p><h3 id="_5-以关键字为基础执行上个的命令" tabindex="-1">5. 以关键字为基础执行上个的命令 <a class="header-anchor" href="#_5-以关键字为基础执行上个的命令" aria-label="Permalink to “5. 以关键字为基础执行上个的命令”">​</a></h3><p>我们可以以关键字为基础执行上次执行的命令。可以从下面的例子中理解：</p><pre><code>$ ls /home &gt; /dev/null						[命令1]
$ ls -l /home/avi/Desktop &gt; /dev/null		                [命令2]	
$ ls -la /home/avi/Downloads &gt; /dev/null	                [命令3]
$ ls -lA /usr/bin &gt; /dev/null				        [命令4]
</code></pre><p>上面我们使用了同样的命令（ls），但有不同的开关和不同的操作文件夹。而且，我们还将输出传递到<code>/dev/null</code>，我们并未显示输出，因而终端依旧很干净。</p><p>现在以关键字为基础执行上个的命令。</p><pre><code>$ ! ls					[命令1]
$ ! ls -l				[命令2]	
$ ! ls -la				[命令3]
$ ! ls -lA				[命令4]
</code></pre><p>检查输出，您将惊奇发现您仅仅使用关键字<code>ls</code>便执行了您已经执行过的命令。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/6.gif" alt="以关键字为基础执行命令"></p><p><em>以关键字为基础执行命令</em></p><p>（LCTT 译注：澄清一下，这种用法会按照命令名来找到最后匹配的命令，不会匹配参数。所以上述执行的四个命令都是执行了 <code>ls -lA /usr/bin &gt; /dev/null</code>，并增加了新的参数而已。）</p><h3 id="_6-操作符的威力" tabindex="-1">6. !!操作符的威力 <a class="header-anchor" href="#_6-操作符的威力" aria-label="Permalink to “6. !!操作符的威力”">​</a></h3><p>您可以使用<code>(!!)</code>运行/修改您上个运行的命令。它将附带一些修改/调整并调用上个命令。让我给您展示一些实际情境。</p><p>昨天我运行了一行脚本来获得我的私有IP，因此我执行了：</p><pre><code>$ ip addr show | grep inet | grep -v &#39;inet6&#39;| grep -v &#39;127.0.0.1&#39; | awk &#39;{print $2}&#39; | cut -f1 -d/
</code></pre><p>接着，我突然发现我需要将上面脚本的输出重定向到一个ip.txt的文件，因此，我该怎么办呢？我该重新输入整个命令并重定向到一个文件么？一个简单的解决方案是使用向上光标键并添加<code>&#39;&gt; ip.txt&#39;</code>来将输出重定向到文件。</p><pre><code>$ ip addr show | grep inet | grep -v &#39;inet6&#39;| grep -v &#39;127.0.0.1&#39; | awk &#39;{print $2}&#39; | cut -f1 -d/ &gt; ip.txt
</code></pre><p>在这里要感谢救世主&quot;向上光标键&quot;。现在，考虑下面的情况，这次我运行了下面这一行脚本。</p><pre><code>$ ifconfig | grep &quot;inet addr:&quot; | awk &#39;{print $2}&#39; | grep -v &#39;127.0.0.1&#39; | cut -f2 -d:
</code></pre><p>一旦我运行了这个脚本，Bash提示符便返回了错误消息<code>&quot;bash: ifconfig: command not found&quot;</code>。原因并不难猜，我运行了本应以root权限的运行的命令。</p><p>所以，怎么解决呢？以root用户登录并且再次键入整个命令就太麻烦了！而且向上导航键也不管用了（LCTT 译注：当你以新的用户身份登录了，是不能用向上光标键找到之前的另外一个用户的命令历史的）。因此，我们需要调用<code>&quot;!!&quot;</code>（去掉引号），它将为那个用户调用上个命令。</p><pre><code>$ su -c !! root
</code></pre><p>这里su是用来切换到root用户的，<code>-c</code>用来以某用户运行特定的命令，最重要的部分是<code>!!</code>，它将被替换为上次运行的命令。当然！您需要提供root密码。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2015/05/7.gif" alt="!!操作符的威力"></p><p><em>!!操作符的威力</em></p><p>我通常在下面的情景中使用<code>!!</code>。</p><p>当我用普通用户来运行apt-get，我通常收到提示说我没有权限来执行。</p><pre><code>$ apt-get upgrade &amp;&amp; apt-get dist-upgrade
</code></pre><p>好吧，有错误。但别担心，使用下面的命令来成功的执行...</p><pre><code>$ su -c !!
</code></pre><p>同样的适用于：</p><pre><code>$ service apache2 start
</code></pre><p>或</p><pre><code>$ /etc/init.d/apache2 start
</code></pre><p>或</p><pre><code>$ systemctl start apache2
</code></pre><p>普通用户不被授权执行那些任务，这样相当于我运行：</p><pre><code>$ su -c &#39;service apache2 start&#39;
</code></pre><p>或</p><pre><code>$ su -c &#39;/etc/init.d/apache2 start&#39;
</code></pre><p>或</p><pre><code>$ su -c &#39;systemctl start apache2&#39;
</code></pre><p>（LCTT 译注：使用<code>!!</code>之前，一定要确认你执行的是什么命令！另外，在 root 身份下，千万不要养成使用它的习惯，因为你总是会在不合适的目录执行不合适的命令！）</p><h3 id="_7-运行一个影响所有除了-file-name-的文件命令" tabindex="-1">7.运行一个影响所有除了![FILE_NAME]的文件命令 <a class="header-anchor" href="#_7-运行一个影响所有除了-file-name-的文件命令" aria-label="Permalink to “7.运行一个影响所有除了![FILE_NAME]的文件命令”">​</a></h3><p><code>!</code>（逻辑非）能用来对除了<code>&#39;!&#39;</code>后的文件的所有的文件/扩展名执行命令。</p><p>A.从文件夹移除所有文件，2.txt除外。</p><pre><code>$ rm !(2.txt)
</code></pre><p>B.从文件夹移除所有的文件类型，pdf类型除外。</p><pre><code>$ rm !(*.pdf)
</code></pre><h3 id="_8-检查某个文件夹-比如-home-avi-tecmint-是否存在-并打印" tabindex="-1">8.检查某个文件夹（比如/home/avi/Tecmint）是否存在？并打印 <a class="header-anchor" href="#_8-检查某个文件夹-比如-home-avi-tecmint-是否存在-并打印" aria-label="Permalink to “8.检查某个文件夹（比如/home/avi/Tecmint）是否存在？并打印”">​</a></h3><p>这里，我们使用<code>&#39;! -d&#39;</code>来验证文件夹是否存在，当文件夹不存在时，将使用其后跟随AND操作符<code>(&amp;&amp;)</code>进行打印，当文件夹存在时，将使用OR操作符<code>(||)</code>进行打印。</p><p>逻辑上，当<code>[ ! -d /home/avi/Tecmint ]</code>的输出为0时，它将执行AND逻辑符后面的内容，否则，它将执行OR逻辑符<code>(||)</code>后面的内容。</p><pre><code>$ [ ! -d /home/avi/Tecmint ] &amp;&amp; printf &#39;\\nno such /home/avi/Tecmint directory exist\\n&#39; || printf &#39;\\n/home/avi/Tecmint directory exist\\n&#39;
</code></pre><h3 id="_9-检查某文件夹是否存在-如果不存在则退出该命令" tabindex="-1">9.检查某文件夹是否存在？如果不存在则退出该命令 <a class="header-anchor" href="#_9-检查某文件夹是否存在-如果不存在则退出该命令" aria-label="Permalink to “9.检查某文件夹是否存在？如果不存在则退出该命令”">​</a></h3><p>类似于上面的情况，但这里当期望的文件夹不存在时，该命令会退出。</p><pre><code>$ [ ! -d /home/avi/Tecmint ] &amp;&amp; exit
</code></pre><h3 id="_10-如果您的home文件夹内不存在一个文件夹-比方说test-则创建它" tabindex="-1">10.如果您的home文件夹内不存在一个文件夹（比方说test），则创建它 <a class="header-anchor" href="#_10-如果您的home文件夹内不存在一个文件夹-比方说test-则创建它" aria-label="Permalink to “10.如果您的home文件夹内不存在一个文件夹（比方说test），则创建它”">​</a></h3><p>这是脚本语言中的一个常用的实现，当期望的文件夹不存在时，创建一个。</p><pre><code>[ ! -d /home/avi/Tecmint ] &amp;&amp; mkdir /home/avi/Tecmint
</code></pre><p>这便是全部了。如果您知道或偶尔遇到其他值得了解的<code>&#39;!&#39;</code>使用方法，请您在反馈的地方给我们提建议。保持联系！</p><hr>`,85)),r("p",null,[e[6]||(e[6]=o("via: ",-1)),p(t,{href:"http://www.tecmint.com/mysterious-uses-of-symbol-or-operator-in-linux-commands/"},{default:a(()=>[...e[5]||(e[5]=[o("http://www.tecmint.com/mysterious-uses-of-symbol-or-operator-in-linux-commands/",-1)])]),_:1})]),r("p",null,[e[10]||(e[10]=o("作者：",-1)),p(t,{href:"http://www.tecmint.com/author/avishek/"},{default:a(()=>[...e[7]||(e[7]=[o("Avishek Kumar",-1)])]),_:1}),e[11]||(e[11]=o(" 译者：",-1)),p(t,{href:"https://github.com/wwy-hust"},{default:a(()=>[...e[8]||(e[8]=[o("wwy-hust",-1)])]),_:1}),e[12]||(e[12]=o(" 校对：",-1)),p(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[9]||(e[9]=[o("wxy",-1)])]),_:1})]),r("p",null,[e[15]||(e[15]=o("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[13]||(e[13]=[o("LCTT",-1)])]),_:1}),e[16]||(e[16]=o(" 原创翻译，",-1)),p(t,{href:"https://linux.cn/"},{default:a(()=>[...e[14]||(e[14]=[o("Linux中国",-1)])]),_:1}),e[17]||(e[17]=o(" 荣誉推出",-1))])])}const _=n(m,[["render",l]]);export{T as __pageData,_ as default};
